// Create a vector to store the nearest neighbors as pairs of (distance, index)
std::vector<std::pair<double, size_t>> neighbors;

// Reserve space for k neighbors
neighbors.reserve(k);

// Calculate squared distances from searchPoint to all points (avoiding sqrt for performance)
for (size_t i = 0; i < points.size(); ++i)
{
    double dx = points[i].X - searchPoint.X;
    double dy = points[i].Y - searchPoint.Y;
    double dz = points[i].Z - searchPoint.Z;
    double distanceSquared = dx * dx + dy * dy + dz * dz;
    neighbors.emplace_back(distanceSquared, i);
}

// Sort the neighbors based on distance (ascending order)
std::sort(neighbors.begin(), neighbors.end(),
    [](const auto& a, const auto& b) { return a.first < b.first; });

// Prepare the result vector
std::vector<size_t> result;
result.reserve(k);

// Take the first k elements (or all if there are fewer than k points)
size_t elementsToTake = std::min(k, neighbors.size());
for (size_t i = 0; i < elementsToTake; ++i)
{
    result.push_back(neighbors[i].second);
}

return result;

